package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 计划内一条占用，区间左闭右开 [startUtc, endUtc)。
 *
 * <p>两种形态：{@code platformId} 为空时为仅按区段裁决的普通占用；
 * 非空时为编组到发站台占用，携带调度员登记的编组三要素，发布成功后固化
 * {@code capabilityVersion}（当时站台能力版本，能力随后升级也不改写历史）。
 *
 * @param id                   主键
 * @param planId               所属计划 id
 * @param seq                  计划内序号，保持提交顺序
 * @param trainNo              列车编号
 * @param sectionId            区段 ID
 * @param startUtc             占用开始时刻（含），UTC
 * @param endUtc               占用结束时刻（不含），UTC，必须晚于 startUtc
 * @param platformId           站台业务键，可空；非空表示站台到发占用
 * @param consistLengthMeters  编组长度，单位米；站台占用时非空且为正
 * @param powerSystem          编组供电制式标识（如 AC25KV/DC1500V）；站台占用时非空
 * @param accessibleRequired   是否需要无障碍服务；站台占用时非空，TRUE 需要
 * @param capabilityVersion    发布时固化的站台能力版本；草稿与普通占用为空
 */
public record Occupancy(long id, long planId, int seq, String trainNo, String sectionId,
                        Instant startUtc, Instant endUtc, String platformId,
                        Integer consistLengthMeters, String powerSystem,
                        Boolean accessibleRequired, Integer capabilityVersion) {

    /** 是否为编组到发站台占用。 */
    public boolean platformOccupancy() {
        return platformId != null;
    }
}

package com.example.starter.plan.model;

import java.util.List;

/**
 * 站台当前能力。能力由站台管理方登记，任一属性变更都会产生新版本，历史不可变。
 *
 * @param platformId      站台业务键，全局唯一
 * @param platformName    站台显示名称
 * @param maxLengthMeters 可接纳编组长度上限，单位米；编组长度等于上限视为适配
 * @param powerSystems    兼容供电制式集合（归一化去重字典序）
 * @param accessible      是否具备无障碍服务能力，TRUE 具备
 * @param version         当前能力版本，首次登记为 1
 * @param createdAt       首次登记时刻，UTC 毫秒
 * @param updatedAt       最近能力变更时刻，UTC 毫秒；能力无变化的重复登记不更新
 */
public record Platform(String platformId, String platformName, int maxLengthMeters,
                       List<String> powerSystems, boolean accessible, int version,
                       long createdAt, long updatedAt) {
}

package com.example.starter.plan.model;

import java.util.List;

/**
 * 站台能力的一个不可变历史版本快照。历史发布记录通过 capabilityVersion 指向当时版本。
 *
 * @param id              主键
 * @param platformId      站台业务键
 * @param version         能力版本号
 * @param maxLengthMeters 该版本长度上限，单位米
 * @param powerSystems    该版本兼容供电制式集合（归一化去重字典序）
 * @param accessible      该版本是否具备无障碍服务能力
 * @param createdAt       该版本产生时刻，UTC 毫秒
 */
public record PlatformCapabilityHistory(long id, String platformId, int version,
                                        int maxLengthMeters, List<String> powerSystems,
                                        boolean accessible, long createdAt) {
}

