COMMENT ON COLUMN rail_platform_capability_history.created_at IS '该版本产生时刻，UTC 毫秒';
CREATE INDEX IF NOT EXISTS idx_rail_platform_history_platform ON rail_platform_capability_history (platform_id, version);

