                                    String sectionId, Instant startUtc, Instant endUtc,
                                    int consistLengthMeters, String powerSystem,
                                    boolean accessibleRequired, int capabilityVersion) {
}

package com.example.starter.plan.web.dto;

/**
 * 单条站台不适配原因。
 *
 * @param reasonCode 原因码：LENGTH_EXCEEDED 超长 / POWER_INCOMPATIBLE 制式不兼容 /
 *                   ACCESSIBILITY_UNAVAILABLE 无障碍能力不满足 / PLATFORM_NOT_FOUND 站台未登记
 * @param message    人类可读说明（含实际与要求值，单位米）
 */
public record IncompatibilityView(String reasonCode, String message) {
}

package com.example.starter.plan.web.dto;

import java.time.Instant;

/**
 * 与候选/申请窗口重叠的一条已生效站台占用（左闭右开，相邻不算重叠）。
 */
public record PlatformWindowConflictView(String scheduleKey, String trainNo,
                                         Instant startUtc, Instant endUtc) {
}

package com.example.starter.plan.web.dto;

import java.util.List;

/**
 * 候选站台视图：调度员查询某编组需求与 UTC 窗口时，每个站台返回当前能力版本、
 * 逐条不适配原因，以及与该窗口重叠的在生效占用；available 为 TRUE 表示
 * 能力适配且窗口空闲，可一次登记到发占用。
 */
public record CandidatePlatformView(String platformId, String platformName, int maxLengthMeters,
                                    List<String> powerSystems, boolean accessible, int version,
                                    boolean compatible,
                                    List<IncompatibilityView> incompatibilities,
                                    List<PlatformWindowConflictView> windowConflicts,
                                    boolean available) {
}

